import sys
def find(x,par):
  #根そのものならそれを出力、そうじゃなければ上を探す
  if par[x]==x:
    return x
  else:
    return find(par[x],par)

def union(x,y,par,rank):
  x=find(x,par)
  y=find(y,par)

  if x!=y:
    #rankは属する根の番号
    if rank[x]<rank[y]:
      par[x]=y
    else:
      par[y]=x
      if rank[x]==rank[y]:
        rank[x]+=1

def same(x,y,par):
  return find(x,par)==find(y,par)

