def fill_zeros_with_last(A):
    for i in range(len(A)):
        arr = A[i]
        prev = np.arange(arr.size)
        prev[arr == 0] = 0
        np.maximum.accumulate(prev, out=prev)
        A[i] = arr[prev]
    return A

