#グラフ上でのBFS
#s=始点 n=頂点数 e=隣接リスト
def glaph_bfs(s,n,e):
  Q=[s]
  visited={s}
  while Q:
    P=[]
    for i in Q:
      for j,_ in e[i]:
        if j in visited:continue
        visited.add(j)
        P.append(j)
    Q=P
  return visited


