class UnionFind():
    def __init__(self, n):
        self.n = n
        self.par = list(range(n))
        self.rank = [1]*n

    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def unit(self,x,y):
        x, y = self.find(x), self.find(y)
        if x==y: return
        if self.rank[x] < self.rank[y]:
            x,y = y,x
        self.rank[x] += self.rank[y]
        self.par[y] = x

