		return (f[n] * ((fi[k] * fi[n - k]) % p)) % p
	for i in range(1, K + 1):
		s = (comb_p(K-1, i-1) * (comb_p(N-K-1, i-2) + 2 * comb_p(N-K-1, i-1) + comb_p(N-K-1,i)) % p) % p
