def inv(a, p):
	power_a = [a]
	b_p = format(p - 2, 'b')
	ans = 1
	for i in range(len(b_p)):
		power_a.append((power_a[-1] ** 2) % p)
	for i in range(len(b_p)):
		if b_p[-i-1] == "1":
			ans = (ans * power_a[i]) % p
	return ans

