def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(n, m, d):
    t = (n-d)
    if d != 0:
        t *= 2
    return t/(n**2) * (m-1)


def main():
    n, m, d = read_int_n()


    print(slv(n, m, d))


