def bruteforce():
    total = 0
    for i in range(n-1):
        for j in range(i+1, n):
            for k in range(m-1):
                for l in range(k+1, m):
                    total += (x[j]-x[i]) * (y[l]-y[k])
    return total % MOD

def solve():
    width = 0
    for i in range(1, n):
        w = x[i] - x[i-1]
