def bellnabFord(edges, src, N):
    inf = float('inf')
    dist = [inf for i in range(N)]
    dist[src] = 0

    for i in range(2*N):
        for s, d, c in edges:
            if dist[d] > dist[s]+c:
                dist[d] = dist[s]+c
                if i >= N: #N回目以降の更新では-infに。(数字の大きさに影響されない)
                    dist[d] = -float('inf')

            if i == N-1:
                prev = dist[-1]
    return (prev, dist[-1])


