def xyz(n: int) -> List[int]:
    result = [0] * n
    for x in range(1, 100):
        for y in range(1, 100):
            for z in range(1, 100):
                m = x ** 2 + y ** 2 + z ** 2 + x * y + y * z + z * x
                if m > n:
                    break
                result[m - 1] += 1

    return result


