        # plから始まり, pr - pl以下で終わる列車を数える
        cnt = 0
        for i, ppl in enumerate(range(pl, pr + 1)):
            cnt += rng[ppl][pr - pl - i]
        ans.append(cnt)

    for a in ans:
        print(a)


